'use client';

import { useQuery } from '@tanstack/react-query';

import { useApi } from '../../../lib/providers';
import { Card, EmptyState, ErrorNotice, Spinner } from '../../../components/ui';
import styles from '../../../components/ui.module.css';

/**
 * One campaign's performance and what to post next.
 *
 * The suggestions come from the API's own aggregation of this campaign's
 * snapshots. They are not generated by a model - see
 * `apps/api/src/analytics/suggestions.ts` for why - so reloading the page shows
 * the same advice, and the rationale names the number it came from.
 */
export function CampaignAnalytics({ campaignId }: { campaignId: string }) {
  const api = useApi();

  const analytics = useQuery({
    queryKey: ['analytics', 'campaign', campaignId],
    queryFn: () => api.campaigns.analytics(campaignId),
  });

  if (analytics.isLoading) {
    return <Spinner label="Loading campaign analytics" />;
  }

  if (analytics.isError) {
    return (
      <ErrorNotice
        message="Could not load analytics for this campaign."
        onRetry={() => void analytics.refetch()}
      />
    );
  }

  if (analytics.data === undefined) {
    return null;
  }

  const { totals, suggestions, publications, series } = analytics.data;
  const maxReach = Math.max(1, ...series.map((point) => point.reach));

  return (
    <>
      <Card
        title="Performance"
        description="Latest snapshot per publication. A post sent to two platforms counts twice in the totals, once per audience."
      >
        <section className={styles.statGrid} aria-label="Campaign totals">
          <Stat label="Reach" value={totals.reach} />
          <Stat label="Likes" value={totals.likes} />
          <Stat label="Comments" value={totals.comments} />
          <Stat label="Clicks" value={totals.clicks} />
          <Stat label="Engagement rate" value={`${(totals.engagementRate * 100).toFixed(1)}%`} />
          <Stat label="Published" value={`${totals.published}/${totals.posts}`} />
        </section>

        {series.length === 0 ? (
          <EmptyState
            title="No metrics yet"
            description="Numbers appear after a post is published and the analytics worker has synced it. The first sync runs a few minutes after publishing."
          />
        ) : (
          <div className={styles.tableWrap}>
            <table className={styles.table}>
              <caption className={styles.cardDescription}>
                Daily totals. One snapshot per publication per day, so a worker that runs six times
                today does not six-fold the chart.
              </caption>
              <thead>
                <tr>
                  <th scope="col">Day</th>
                  <th scope="col">Reach</th>
                  <th scope="col" className={styles.numeric}>
                    Likes
                  </th>
                  <th scope="col" className={styles.numeric}>
                    Comments
                  </th>
                  <th scope="col" className={styles.numeric}>
                    Clicks
                  </th>
                </tr>
              </thead>
              <tbody>
                {series.map((point) => (
                  <tr key={point.date}>
                    <th scope="row">{point.date}</th>
                    <td>
                      <div className={styles.progress} aria-hidden="true">
                        <div
                          className={styles.progressFill}
                          style={{ width: `${Math.round((point.reach / maxReach) * 100)}%` }}
                        />
                      </div>
                      <span className={styles.cardDescription}>{point.reach.toLocaleString()}</span>
                    </td>
                    <td className={styles.numeric}>{point.likes.toLocaleString()}</td>
                    <td className={styles.numeric}>{point.comments.toLocaleString()}</td>
                    <td className={styles.numeric}>{point.clicks.toLocaleString()}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </Card>

      <Card
        title="What to post next"
        description="Ranked from this campaign's own numbers, not guessed."
      >
        {suggestions.length === 0 ? (
          <EmptyState
            title="Not enough data yet"
            description="Publish a post and the next round of suggestions will cite its engagement."
          />
        ) : (
          <ol className={styles.suggestionList}>
            {suggestions.map((suggestion) => (
              <li key={`${suggestion.type}-${suggestion.title}`} className={styles.suggestion}>
                <h3>
                  {suggestion.title} <span className={styles.badge}>{suggestion.type}</span>
                </h3>
                <p>{suggestion.rationale}</p>
              </li>
            ))}
          </ol>
        )}
      </Card>

      <Card title="Publications">
        {publications.length === 0 ? (
          <EmptyState
            title="Nothing published"
            description="Approve a post and schedule it to a connected account."
          />
        ) : (
          <div className={styles.tableWrap}>
            <table className={styles.table}>
              <thead>
                <tr>
                  <th scope="col">Post</th>
                  <th scope="col">Platform</th>
                  <th scope="col">Published</th>
                  <th scope="col" className={styles.numeric}>
                    Reach
                  </th>
                  <th scope="col" className={styles.numeric}>
                    Likes
                  </th>
                  <th scope="col" className={styles.numeric}>
                    Comments
                  </th>
                  <th scope="col" className={styles.numeric}>
                    Clicks
                  </th>
                </tr>
              </thead>
              <tbody>
                {publications.map((publication) => (
                  <tr key={`${publication.postId}-${publication.publishJobId ?? 'draft'}`}>
                    <td>
                      {publication.type}
                      {publication.caption !== null && (
                        <span className={styles.cardDescription}>
                          {' '}
                          · {truncate(publication.caption, 60)}
                        </span>
                      )}
                    </td>
                    <td>{publication.platform ?? '—'}</td>
                    <td>
                      {publication.publishedAt === null
                        ? (publication.publishStatus ?? publication.status)
                        : new Date(publication.publishedAt).toLocaleDateString()}
                      {publication.externalUrl !== null && (
                        <>
                          {' · '}
                          <a
                            href={publication.externalUrl}
                            target="_blank"
                            rel="noreferrer noopener"
                          >
                            View
                          </a>
                        </>
                      )}
                    </td>
                    <td className={styles.numeric}>
                      {publication.metrics?.reach.toLocaleString() ?? '—'}
                    </td>
                    <td className={styles.numeric}>
                      {publication.metrics?.likes.toLocaleString() ?? '—'}
                    </td>
                    <td className={styles.numeric}>
                      {publication.metrics?.comments.toLocaleString() ?? '—'}
                    </td>
                    <td className={styles.numeric}>
                      {publication.metrics?.clicks.toLocaleString() ?? '—'}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </Card>
    </>
  );
}

function Stat({ label, value }: { label: string; value: number | string }) {
  return (
    <div className={styles.stat}>
      <p className={styles.statLabel}>{label}</p>
      <p className={styles.statValue}>
        {typeof value === 'number' ? value.toLocaleString() : value}
      </p>
    </div>
  );
}

function truncate(value: string, max: number): string {
  return value.length <= max ? value : `${value.slice(0, max - 1)}…`;
}
